const pragueDistricts = Array.from({ length: 10 }, (_, i) => `Praha ${i + 1}`)

const activeRegions = new Set(projects.map(p => p.region))
const activeDistricts = new Set(projects.filter(p => p.region === 'Praha').map(p => p.district))

const sortedRegions = computed(() => {
  return [...regions].sort((a, b) => {
    if (a.name === 'Praha') return -1;
    if (b.name === 'Praha') return 1;
    const aActive = activeRegions.has(a.name);
    const bActive = activeRegions.has(b.name);
    if (aActive && !bActive) return -1;
    if (!aActive && bActive) return 1;
    return 0;
  });
})

// Kraje musí být čitelné i na světlém pozadí — původní fill-ink/5 s opacity-60
// bylo na canvasu prakticky neviditelné. Hover používá akcentní barvu z manuálu.
const regionClass = (name: string) => {
  if (!activeRegions.has(name)) {
    return 'fill-muted stroke-line cursor-not-allowed'
  }
  if (props.selectedRegion === name) return 'fill-ink stroke-ink cursor-pointer'
  if (hoveredRegion.value === name) return 'fill-accent stroke-ink cursor-pointer'
  return 'fill-paper stroke-ink/45 cursor-pointer'
}

const isFilterActive = computed(() => props.selectedRegion !== 'Všechny regiony' || props.selectedDistrict !== '')

const selectRegion = (name: string) => {
  if (!activeRegions.has(name)) return
  if (props.selectedRegion === name) {
    emit('update:region', 'Všechny regiony')
    emit('update:district', '')
  } else {
    emit('update:region', name)
    emit('update:district', '')
  }
}

const selectDistrict = (name: string) => {
  if (!activeDistricts.has(name)) return
  emit('update:district', props.selectedDistrict === name ? '' : name)
}
</script>

<template>
  <div class="grid gap-8 lg:grid-cols-[1fr_400px] xl:grid-cols-[1.3fr_0.7fr] items-stretch" @mousemove="onMouseMove">
    
    <!-- SVG MAP - LEFT -->
    <div class="rounded-3xl border border-line bg-canvas p-4 md:p-6 lg:p-8 flex flex-col justify-start pt-12 xl:pt-16 items-center relative overflow-hidden h-full">
      <div class="w-full max-w-[700px] relative">
       
         
         <svg viewBox="0 0 953 549" class="w-full h-auto drop-shadow-sm">
           <g v-for="region in regions" :key="region.id">
             <path
               :d="region.d"
               :class="regionClass(region.name)"
               class="stroke-1 transition-colors duration-200"
               @click="selectRegion(region.name)"
               @mouseenter="hoveredRegion = region.name"
               @mouseleave="hoveredRegion = ''"
             >
             </path>
           </g>
         </svg>
      </div>
    </div>

    <!-- BUTTONS - RIGHT -->
    <div class="rounded-3xl border border-line bg-paper p-6 md:p-8 flex flex-col h-full">

      <div class="overflow-y-auto pr-2 custom-scrollbar flex-1">
        <div class="grid grid-cols-2 gap-3 items-start h-full align-top">
          <template v-for="region in sortedRegions" :key="region.id">
            
            <button
              type="button"
              class="flex w-full items-center justify-between rounded-full border px-4 sm:px-5 py-3 text-label uppercase tracking-[0.1em] font-bold transition-all duration-300"
              :class="[
                !activeRegions.has(region.name) ? 'border-line/60 bg-canvas/50 text-ink/45 cursor-not-allowed opacity-80' :
                selectedRegion === region.name ? 'border-ink bg-ink text-paper shadow-sm cursor-pointer' : 
                hoveredRegion === region.name ? 'border-ink bg-ink/5 text-ink cursor-pointer' : 'border-line bg-transparent text-ink/70 hover:border-ink hover:text-ink cursor-pointer'
              ]"
              :disabled="!activeRegions.has(region.name)"
              @click="selectRegion(region.name)"
              @mouseenter="hoveredRegion = region.name"
              @mouseleave="hoveredRegion = ''"
            >
              <span class="truncate pr-2">{{ region.name }}</span>
              <svg v-if="selectedRegion === region.name" class="h-3 w-3 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="3"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/></svg>
            </button>

            <!-- Prague Sub-Districts Dropdown spans both columns -->
            <div v-if="region.name === 'Praha' && selectedRegion === 'Praha'" class="col-span-2 mb-2 p-4 rounded-3xl bg-canvas border border-line">
               <p class="text-label uppercase tracking-[0.2em] text-secondary font-bold mb-3 text-center">Pražské části</p>
               <div class="grid grid-cols-5 gap-2">
                 <button
                   v-for="district in pragueDistricts"
                   :key="district"
                   type="button"
                   class="rounded-lg border px-1 py-2 text-[9px] uppercase tracking-wider font-bold transition-all duration-300 w-full flex items-center justify-center"
                   :class="[
                     !activeDistricts.has(district) ? 'border-line/60 bg-canvas/50 text-ink/45 cursor-not-allowed opacity-80' :
                     selectedDistrict === district ? 'border-ink bg-ink text-paper shadow-sm cursor-pointer' : 'border-line bg-paper text-ink/70 hover:border-ink hover:text-ink text-center cursor-pointer'
                   ]"
                   :disabled="!activeDistricts.has(district)"
                   @click="selectDistrict(district)"
                   @mouseenter="hoveredDistrict = district"
                   @mouseleave="hoveredDistrict = ''"
                 >
                   <!-- Shorten "Praha X" to "P X" or just "X" on very small mobile if needed, but 9px is small enough -->
                   {{ district.replace('Praha ', '') }}
                 </button>
               </div>
            </div>
          </template>
        </div>
      </div>
    </div>

    <!-- Global Floating Tooltip -->
    <div 
      v-if="hoveredRegion || hoveredDistrict"
      class="fixed bg-ink text-paper text-label font-bold uppercase tracking-widest px-4 py-2 sm:px-6 sm:py-3 rounded-full pointer-events-none z-[100] shadow-xl text-center whitespace-nowrap"
      :style="{ left: mouseX + 'px', top: mouseY + 'px', transform: 'translate(-50%, -150%)' }"
    >
      <template v-if="hoveredDistrict">
        <span v-if="!activeDistricts.has(hoveredDistrict)">V této části nebyl nominován žádný projekt</span>
        <span v-else>{{ hoveredDistrict }}</span>
      </template>
      <template v-else-if="hoveredRegion">
         <span v-if="!activeRegions.has(hoveredRegion)">V tomto regionu nebyl nominován žádný projekt</span>
         <span v-else-if="hoveredRegion === 'Praha' && selectedRegion !== 'Praha'">Praha – Vyberte napravo</span>
         <span v-else>{{ hoveredRegion }}</span>
      </template>
    </div>

  </div>
</template>

<style scoped>
.custom-scrollbar::-webkit-scrollbar {
  width: 4px;
}
.custom-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scrollbar::-webkit-scrollbar-thumb {
  background: var(--color-line);
  border-radius: 4px;
}
</style>
